mapper.select:
SELECT TOUR_ID, FIELD_NM, STATUS_CD, INFO_TEXT, SOURCE_URL, SOURCE_TITLE, CHECKED_DT
FROM TB_TRMA_TOUR_INFO_AI
WHERE TOUR_ID = #{tourId}

SELECT b.TOUR_ID AS tourId, b.${field} AS source
FROM TB_TRMA_TOUR_LIST b
WHERE b.USE_YN = 'Y' AND b.${column} IS NULL AND b.${field} REGEXP '[가-힣]'
  AND b.TOUR_ID > #{afterTourId}
ORDER BY b.TOUR_ID
LIMIT #{limit}
